function compose(...fns) {
  if (fns.length === 0) return (x) => x;
  return fns.reduce((a, b) => (...args) => a(b(...args)));
}

const inc = (n) => n + 1;
const dbl = (n) => n * 2;
compose(inc, dbl)(3); // 7  because inc(dbl(3))
```

Right-to-left matches mathematical composition. Use `pipe` (left-to-right) if you prefer reading in execution order.

